	private static LmdbStore openStore(File dataDir, boolean sketchEnabled) {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc")
				.setFrontierEstimatorMode(FrontierEstimatorMode.AUTHORITATIVE)
				.setFrontierSynopsisBudgetBytes(1024L * 1024L)
				.setSketchEstimatorEnabled(sketchEnabled)
				.setSketchEstimatorColdSynopsisCapacity(sketchEnabled ? 256 : 0);
		LmdbStore store = new LmdbStore(dataDir, config);
		store.init();
		return store;
	}

	private static void addStatement(LmdbStore store, String suffix) {
		try (SailConnection connection = store.getConnection()) {
			connection.begin();
			connection.addStatement(
					VF.createIRI("urn:test:sidecar-stamp:subject:" + suffix),
					VF.createIRI("urn:test:sidecar-stamp:predicate"),
					VF.createLiteral(suffix));
			connection.commit();
		}
	}

	private static void prepareSketchIdentity(LmdbStore store) {
		SketchBasedJoinEstimator estimator = store.getBackingStore().getSketchBasedJoinEstimator();
		if (estimator != null) {
			estimator.rebuild();
			estimator.persistIfDirty();
			estimator.stop();
		}
	}

	private static void trainAndPersistLearnedSurfaces(LmdbStore store) throws Exception {
		LmdbSailStore backingStore = store.getBackingStore();
		backingStore.getEvaluationStatistics().recordFilterOutcome(filter("5"), 20L, 80L);

		LmdbOperatorFeedbackStats operatorStats = operatorStats(store);
		Join observed = join();
		complete(observed, 100L, 10.0d, 20.0d);
		observed.setJoinLeftBindingsConsumedActual(50L);
		observed.setJoinRightBindingsConsumedActual(100L);
		operatorStats.recordOperatorOutcome(observed);
		operatorStats.recordFanout(33L, LmdbLeoSurfaceStats.BoundPosition.OBJECT, 44L, 123L, 1L);
		assertNotNull(operatorStats.estimate(join(), 200.0d, 100.0d, 10.0d, 20.0d));
		assertTrue(operatorStats.evidence(LeoSurfaceKey.fanout(33L, "object", 44L)).isPresent());

		field(backingStore, "filterSelectivityStats", LmdbFilterSelectivityStats.class).persistIfDirty();
		operatorStats.persistIfDirty();
		assertTrue(new File(store.getDataDir(), "join-estimator.rjes.filters").isFile());
		assertTrue(new File(store.getDataDir(), "join-estimator.rjes.operators").isFile());
		assertTrue(new File(store.getDataDir(), "join-estimator.rjes.leo").isFile());
		if (store.getBackingStore().getSketchBasedJoinEstimator() != null) {
			assertTrue(new File(store.getDataDir(), "join-estimator.rjes.cold").isFile());
		}
	}

	private static void assertLearnedSurfacesPresent(LmdbStore store, boolean sketchEnabled) throws Exception {
		EvaluationStatistics.FilterPassEstimate filterEstimate = store.getBackingStore()
				.getEvaluationStatistics()
				.estimateFilterPass(filter("6"));
		LmdbOperatorFeedbackStats.OperatorEstimate operatorEstimate = operatorStats(store)
				.estimate(join(), 200.0d, 100.0d, 10.0d, 20.0d);
		assertAll(
				() -> assertEquals(EvaluationStatistics.FilterPassEstimate.Source.LEARNED_TEMPLATE,
						filterEstimate.getSource()),
				() -> assertEquals(0.2d, filterEstimate.getPassRatio(), 0.000_001d),
				() -> assertEquals(100L, filterEstimate.getEvidenceCount()),
				() -> assertNotNull(operatorEstimate),
				() -> assertTrue(operatorStats(store)
						.evidence(LeoSurfaceKey.fanout(33L, "object", 44L))
						.isPresent()),
				() -> assertEquals(sketchEnabled, store.getColdFilterSynopsisFootprint().isPresent()));
	}

	private static LmdbOperatorFeedbackStats operatorStats(LmdbStore store) throws Exception {
		return field(store.getBackingStore(), "operatorFeedbackStats", LmdbOperatorFeedbackStats.class);
	}

	private static Filter filter(String constant) {
		Filter[] found = new Filter[1];
		QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, FILTER_QUERY.formatted(constant), null)
				.getTupleExpr()
				.visit(new org.eclipse.rdf4j.query.algebra.helpers.AbstractQueryModelVisitor<RuntimeException>() {
					@Override
					public void meet(Filter node) {
						if (found[0] == null) {
							found[0] = node;
						}
						super.meet(node);
					}
				});
		return found[0];
	}

	private static Join join() {
		return new Join(
				new StatementPattern(Var.of("s"), Var.of("_p1", P1, true, true), Var.of("x")),
				new StatementPattern(Var.of("x"), Var.of("_p2", P2, true, true), Var.of("o")));
	}

	private static void complete(Join node, long actualRows, double plannedRows, double plannedWorkRows) {
		node.setRuntimeTelemetryEnabled(true);
		node.setResultSizeEstimate(plannedRows);
		node.setCostEstimate(plannedWorkRows);
		node.setDoubleMetricPlanned(TelemetryMetricNames.PLANNED_WORK_ROWS, plannedWorkRows);
		node.setResultSizeActual(actualRows);
		node.setLongMetricActual(TelemetryMetricNames.OUTPUT_ROWS_ACTUAL, actualRows);
		node.setLongMetricActual(TelemetryMetricNames.CLOSE_COUNT_ACTUAL, 1L);
		node.setLongMetricActual(TelemetryMetricNames.EXHAUSTED_CLOSE_COUNT_ACTUAL, 1L);
		node.setHasNextCallCountActual(actualRows + 1L);
		node.setHasNextTrueCountActual(actualRows);
	}

	private static int persistedVersion(File sidecar) throws Exception {
		return ByteBuffer.wrap(Files.readAllBytes(sidecar.toPath())).getInt();
	}

	private static int leoPersistedVersion(File sidecar) throws Exception {
		byte[] bytes = Files.readAllBytes(sidecar.toPath());
		ByteBuffer buffer = ByteBuffer.wrap(bytes);
		return buffer.getInt(Integer.BYTES + buffer.getInt(0));
	}

	private static int coldPersistedVersion(File sidecar) throws Exception {
		return ByteBuffer.wrap(Files.readAllBytes(sidecar.toPath())).getInt(Integer.BYTES);
	}

	private static void rewritePersistedVersion(Path sidecar, int version) throws Exception {
		byte[] bytes = Files.readAllBytes(sidecar);
		ByteBuffer.wrap(bytes).putInt(version);
		Files.write(sidecar, bytes);
	}

	private static void rewriteLeoPersistedVersion(Path sidecar, int version) throws Exception {
		byte[] bytes = Files.readAllBytes(sidecar);
		ByteBuffer buffer = ByteBuffer.wrap(bytes);
		buffer.putInt(Integer.BYTES + buffer.getInt(0), version);
		Files.write(sidecar, bytes);
	}

	private static void rewriteColdPersistedVersion(Path sidecar, int version) throws Exception {
		byte[] bytes = Files.readAllBytes(sidecar);
		ByteBuffer.wrap(bytes).putInt(Integer.BYTES, version);
		Files.write(sidecar, bytes);
	}

	private static <T> T field(Object target, String name, Class<T> type) throws Exception {
		Field field = target.getClass().getDeclaredField(name);
		field.setAccessible(true);
		return type.cast(field.get(target));
	}
